,{
"ClauseCode":"1009101"
,"ClauseContent":"<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:10.0pt\">It is agreed and understood that otherwise subject to the terms, exclusions, provisions and conditions contained in the Policy or endorsed thereon and subject to the Insured having paid the agreed extra premium, this insurance shall be extended to cover extra charges for airfreight.</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:10.0pt\">Provided always that such extra charges shall be incurred in connec&shy;tion with any loss of or damage to the insured items recoverable under the Policy.</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:10.0pt\">Provided further that the maximum amount payable under this Endorsement in respect of airfreight shall not exceed the amount stated below during the period of insurance.</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"tab-stops:135.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><b><span style=\"font-size:10.0pt\">Deductible:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 20 % of the indemnifiable extra charges, minimum &hellip;&hellip;&hellip;&hellip;. any one occurrence</span></b></span></span></span></p>\n\n<p style=\"margin-left:1.0in; text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"tab-stops:135.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><b><span style=\"font-size:10.0pt\">Maximum amount payable:</span></b></span></span></span></p>\n\n<p style=\"margin-left:1.0in; text-align:justify; margin:0in 0in 0.0001pt\"><b><span style=\"font-size:10.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Extra premium:</span></span></b></p>"
,"ClauseDescription":"MR.007 Cover of Extra Charges for Airfreight (IDR. 5,000.000.000,-)"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxCreateDateTime":"20200626T041418.696 GMT"
,"pxCreateOperator":"PASKALINAWILMATRINITA"
,"pxCreateOpName":"PASKALINA WILMA TRINITA"
,"pxCreateSystemID":"pegaprodasm83"
