,{
"ClauseCode":"1007668"
,"ClauseContent":"<p style=\"margin: 0in 0in 0.0001pt; text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\"><b>Endorsement 113</b></span></span></p>\n\n<p style=\"margin: 0in 0in 0.0001pt; text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\"><b>Inland Transit</b></span></span></p>\n\n<p style=\"margin: 0in 0in 0.0001pt; text-align: justify;\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">It is agreed and understood that, otherwise subject to the terms, exclusions, provisions and conditions contained in the Policy or endorsed thereon and subject to the insured having paid the agreed extra premium, Section I of this insurance shall be extended to cover loss of or damage to the property insured whilst in transit to the contract site other than on waterways or by air within the territorial limits of &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; provided that the maximum amount payable under this Endorsement does not exceed &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;.. per conveyance.</span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\"><b>Total value of property&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : &nbsp;&nbsp;&nbsp; </b></span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\"><b>Deductible &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :&nbsp;&nbsp;&nbsp;&nbsp; </b></span></span></p>\n\n<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\"><b>Extra Premium &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :</b></span></span></p>"
,"ClauseDescription":"MR.113 inland transit (Limit IDR. 10,000,000,000,- within North Sumatera )"
