,{
"ClauseCode":"1003810"
,"ClauseContent":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">In consideration of the payment of an additional premium this policy extends to indemnity the insured in respect of:</span></span></p>\n\n<p style=\"margin-left: 40px; text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">The cost of removal of debris, demolition and any temporary repairs necessary (including the insured&rsquo;s legal liability for the cost of removal of debris, demolition and temporary repairs in regard to adjoining premises, roadways or waterways as well as on the site) consequent upon the destruction of or damage to any property, insured by the insured&rsquo;s fire policy (or policies) occasioned by fire or any other peril thereby insured against.</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">Provided always:</span></span></p>\n\n<ul>\n\t<li style=\"text-align: justify; font-size: 9px;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">that such cost is not recoverable under any other policy of insurance;</span></span></li>\n\t<li style=\"text-align: justify; font-size: 9px;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">That the indemnity afforded by this insurance shall not apply to or include liability assumed by the insured under any agreement entered into after the commencing date of this insurance unless such liability would have attached to the insured in the absence of such agreement.</span></span></li>\n</ul>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">The liability of the company under this clause in respect of any item shall in no case exceed limit above.</span></span></p>"
,"ClauseDescription":"Removal Of Debris Clause (10% of Loss maximum IDR. 10,000,000,000,-)"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxCreateDateTime":"20200626T043505.437 GMT"
,"pxCreateOperator":"PASKALINAWILMATRINITA"
,"pxCreateOpName":"PASKALINA WILMA TRINITA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"SearchClause":"Removal of Debris Clause"
,"Section":"1"
,"OldClause":[ 
{
"ClauseCode":"1003810"
,"ClauseContent":"<p style=\"margin:0in; margin-bottom:.0001pt; text-align:justify; margin-right:0in; margin-left:0in\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"border: 1pt none windowtext; padding: 0in;\"><span style=\"color:black\">In consideration of the payment of an additional premium this policy extends to indemnity the insured in respect of:</span></span></span></span></span></span></p>\n\n<p style=\"margin:0in; margin-bottom:.0001pt; text-align:justify; margin-right:0in; margin-left:0in\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"border: 1pt none windowtext; padding: 0in;\"><span style=\"color:black\">The cost of removal of debris, demolition and any temporary repairs necessary (including the insured&rsquo;s legal liability for the cost of removal of debris, demolition and temporary repairs in regard to adjoining premises, roadways or waterways as well as on the site) consequent upon the destruction of or damage to any property, insured by the insured&rsquo;s fire policy (or policies) occasioned by fire or any other peril thereby insured against.</span></span></span></span></span></span></p>\n\n<p style=\"margin:0in; margin-bottom:.0001pt; text-align:justify; margin-right:0in; margin-left:0in\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"border: 1pt none windowtext; padding: 0in;\"><span style=\"color:black\">Provided always:</span></span></span></span></span></span></p>\n\n<p style=\"margin:0in; margin-bottom:.0001pt; text-align:justify; margin-right:0in; margin-left:0in\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"border: 1pt none windowtext; padding: 0in;\"><span style=\"color:black\">that such cost is not recoverable under any other policy of insurance; </span></span></span></span></span></span></p>\n\n<p style=\"margin:0in; margin-bottom:.0001pt; text-align:justify; margin-right:0in; margin-left:0in\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"border: 1pt none windowtext; padding: 0in;\"><span style=\"color:black\">That the indemnity afforded by this insurance shall not apply to or include liability assumed by the insured under any agreement entered into after the commencing date of this insurance unless such liability would have attached to the insured in the absence of such agreement.</span></span></span></span></span></span></p>\n\n<p style=\"margin:0in 0in 0.0001pt; margin-right:0in; margin-left:0in\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\"><span style=\"border: 1pt none windowtext; padding: 0in;\"><span style=\"color:black\">The liability of the company under this clause in respect of any item shall in no case exceed limit above.</span></span></span></span></p>"
,"ClauseDescription":"Removal Of Debris Clause (10% of Loss maximum IDR. 10,000,000,000,-)"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxCreateDateTime":"20200626T043505.437 GMT"
,"pxCreateOperator":"PASKALINAWILMATRINITA"
,"pxCreateOpName":"PASKALINA WILMA TRINITA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"SearchClause":"Removal of Debris Clause"
,"Section":"1"
}
] 
