,{
"ClauseCode":"1004190"
,"ClauseContent":"<p style=\"margin:0in 0in 0.0001pt; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"border:none windowtext 1.0pt; font-size:10.0pt; padding:0in\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:black\">It is understood and agreed that this policy will also indemnify against the necessarily incurred cost of re-writing of plans and drawings or other contract documents lost destroyed or damaged as a result of a perils insured hereunder providing such loss destruction or damage occurs at the project site.</span></span></span></span></span></span></span></p>\n\n<p style=\"margin:0in 0in 0.0001pt; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"vertical-align:baseline\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"border:none windowtext 1.0pt; font-size:10.0pt; padding:0in\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:black\">Such indemnification shall however be limited to :</span></span></span></span></span></span></span></p>\n\n<div style=\"border-top:solid #eeeeee 1.0pt; padding:2.0pt 0in 0in 0in; margin-left:-3.0pt; margin-right:0in\">\n<ol>\n\t<li style=\"border: none; padding: 0in; margin: 0in 0in 0.0001pt; text-align: justify; font-size: 10pt;\"><span style=\"background:white\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"tab-stops:list .5in\"><span style=\"vertical-align:baseline\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"border:none windowtext 1.0pt; font-size:10.0pt; padding:0in\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:black\">a maximum amount of &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;. each and every occurrence or series of occurrences arising out of any one event.</span></span></span></span></span></span></span></span></span></li>\n\t<li style=\"border: none; padding: 0in; margin: 0in 0in 0.0001pt; text-align: justify; font-size: 10pt;\"><span style=\"border:none windowtext 1.0pt; font-size:10.0pt; padding:0in\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:black\">the cost of labour expended in such re-writing or re-drawing including all necessary overtime or research</span></span></span></li>\n</ol>\n</div>"
,"ClauseDescription":"Plan and Document Clause (Limit IDR. 2,000,000,000,-)"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxCreateDateTime":"20200626T043811.515 GMT"
,"pxCreateOperator":"PASKALINAWILMATRINITA"
