,"Section":"1"
,"OldClause":[ 
{
"ClauseCode":"1008121"
,"ClauseContent":"<p style=\"text-align:justify; margin:0in 0in 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"text-autospace:ideograph-numeric\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">This Agreement does not cover any liability for :</span></span></span></p>\n\n<ol>\n\t<li style=\"text-align: justify; margin: 0in 0in 0.0001pt; font-size: 12pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list .5in\"><span style=\"text-autospace:ideograph-numeric\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Personal Injury or Bodily Injury or loss of damage to or loss of use property directly or indirectly caused by seepage, pollution or contamination provided always that this paragraph shall not apply to liability for personal Injury or Bodily Injury or loss of or physical damage to or destruction of tangible property or loss of use of such property damage or destroyed, where such seepage pollution or contamination is caused by a sudden. Unintended and unexpected happening during the period of this Insurance.</span></span></span></span></li>\n\t<li style=\"text-align: justify; margin: 0in 0in 0.0001pt; font-size: 12pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list .5in\"><span style=\"text-autospace:ideograph-numeric\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">The cost of removing mollifying or cleaning up seeping. polluting or contaminating substance unless the seepage pollution or contamination is caused by sudden, unintended and unexpected happening during the period of this insurance.</span></span></span></span></li>\n\t<li style=\"text-align: justify; margin: 0in 0in 0.0001pt; font-size: 12pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list .5in\"><span style=\"text-autospace:ideograph-numeric\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Fines, penalties, punitive or exemplary damage.</span></span></span></span></li>\n</ol>\n\n<p><span lang=\"IN\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">This clause shall not extend this Agreement to cover any liability which would not have been covered under this agreement had this clause not been attached.</span></span></p>"
,"ClauseDescription":"Industries, Seepage, Pollution and Contamination Exclusion Clause (NMA 1685)"
,"FlagOldData":"1"
,"KodeSection":"1"
