,{
"ClauseCode":"1005502"
,"ClauseContent":"<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><b>NUCLEAR ENERGY RISKS EXCLUSION CLAUSE (1994)</b></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><b>(WORLDWIDE EXCLUDING U.S.A. AND CANADA) &ndash; NMA1975(A)</b></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">This agreement shall exclude Nuclear Energy Risk whether such risks are written directly and/or by way of insurance and/or via pools and/or associations.</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">For the purpose of this Agreement Nuclear Energy Risks shall mean all first party and/or third party insurances (other than workers&#39; compensation and/or employers&#39; liability) in respect of:</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<ol style=\"list-style-type:upper-roman\">\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">All property on the site of a nuclear power stations, nuclear reactors, reactor buildings and plant and equipment therein on any site other than a nuclear power station</span></span></span></span></li>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">All property, on any site (including but not limited to the sites referred to in (I) above) used or having been used for:-</span></span></span></span>\n\t<ol style=\"list-style-type:lower-alpha\">\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">the generation of nuclear energy; or</span></span></span></span></li>\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">the production, use or storage of nuclear material</span></span></span></span></li>\n\t</ol>\n\t</li>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">any other property eligible for insurance by the relevant local Nuclear Insurance Pool and/or Association but only to the extent of the requirements of that local pool and/or association</span></span></span></span></li>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">the supply of goods and services to any of the sites, described in the (I) and (II) above, unless such insurances shall exclude the perils of irradiation and contamination by Nuclear Material.</span></span></span></span></li>\n</ol>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Except as under-noted, Nuclear Energy Risks shall not include:</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<ol style=\"list-style-type:lower-roman\">\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">any insurance in respect of the construction or erection or installation or replacement or repair or maintenance or decommissioning of property as described in (I) to (III) above (including contractors&#39; plant and equipment);</span></span></span></span></li>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">any Machinery Breakdown or other Engineering insurance not coming within the scope of (I) above;</span></span></span></span></li>\n</ol>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Provide always that such insurance shall exclude the perils of irradiation and contamination by Nuclear Material.</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">However, the above exemption shall not extend to:-</span></span></span></p>\n\n<ol>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">the provision of any insurance whatsoever in respect of :-</span></span></span></span>\n\n\t<ol style=\"list-style-type:lower-alpha\">\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Nuclear Material;</span></span></span></span></li>\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Any property in the High Radioactivity Zone or Area of any Nuclear Installation as from the introduction of Nucelar Material or &ndash; for reactor installations &ndash; as from fuel loading or first critically where so agreed with the relevant local Nuclear Insurance Pool and/or Association</span></span></span></span></li>\n\t</ol>\n\t</li>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">the provision of any insurance for the under-noted perils:-</span></span></span></span>\n\t<ol style=\"list-style-type:lower-alpha\">\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Fire, lightning, explosion;</span></span></span></span></li>\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Earthquake;</span></span></span></span></li>\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Aircraft and other aerial devices or articles dropped therefrom;</span></span></span></span></li>\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">irradiation and radioactive contamination;</span></span></span></span></li>\n\t\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 54.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">any other peril insured by the relevant local Nuclear Insurance Pool and/or Association</span></span></span></span></li>\n\t</ol>\n\t</li>\n</ol>\n\n<p style=\"margin-left:35.75pt; text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"margin-left:35.75pt; text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">in respect of any other Property not specified in (1) above which directly involves the production, use or storage of Nuclear Material as from the introduction of Nuclear Material info such property.</span></span></span></p>\n\n<p style=\"margin-left:35.75pt; text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Definitions</span></span></span></p>\n\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">&ldquo;Nuclear Material&rdquo; means:-</span></span></span></p>\n\n<ol>\n\t<li style=\"text-align: justify; margin: 0cm 0cm 0.0001pt; font-size: 10pt;\"><span style=\"font-size:12pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"IN\" style=\"font-size:10.0pt\">Nuclear fuel, other than natural uranium or depleted uranium, capabile of producing energy by a self sustaining chain process of nuclear fission outside a Nuclear Reactor, either alone or in combination with some other material; and</span></span></span></span></li>\n</ol>"
,"ClauseDescription":"Nuclear Energy Risk Exclusion"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxCreateDateTime":"20200701T071303.985 GMT"
,"pxCreateOperator":"PASKALINAWILMATRINITA"
,"pxCreateOpName":"PASKALINA WILMA TRINITA"
,"pxCreateSystemID":"pegaprodasm83"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"Section":"1"
,"OldClause":[ 
